"""Autoroute the board generated by build_card.py and add GND pours. Run with KiCad 10 python.

Everything here is shared with the other cards and lives in ../../tools/route_lib.py;
this file is just what is different about this board. Needs Java -- the Freerouting jars
sit in the workspace tools/ directory, or set FREEROUTING_JAR to override.
"""
from pathlib import Path
import sys

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'tools'))
from route_lib import route

route('solderdemon_m68k-gpio', root=Path(__file__).resolve().parents[1], corner=0.0)   # square corners
